document.addEventListener("DOMContentLoaded",function(){const rentOption=document.getElementById("rentOption");const saleOption=document.getElementById("saleOption");const priceDiv=document.querySelector("#priceSlider").closest(".mb-3");const priceRentDiv=document.querySelector("#priceRentSlider").closest(".mb-3");function togglePriceSliders(){if(rentOption.checked){priceRentDiv.style.display="block";priceDiv.style.display="none"}else if(saleOption.checked){priceDiv.style.display="block";priceRentDiv.style.display="none"}else{priceDiv.style.display="block";priceRentDiv.style.display="none"}}
rentOption.addEventListener("change",togglePriceSliders);saleOption.addEventListener("change",togglePriceSliders);togglePriceSliders()})